        // getNegativeDecisionVariableOffset = 0
        // getRhsOffset = 3 (last column)
        double[][] data = {
            {1, 0, 10, 5}, // Row 0: Objective (linked to index 0)
            {0, 1, 20, 8}, // Row 1: Basic for Var 0 (index 0)
            {0, 0, 0, 0},  // Row 2: Basic for Var 1 (index 1)
            {1, 1, 0, -5}  // Row 3: Negative Var row
        };

        // Since SimplexTableau has a complex internal state, we use Mockito to mock the protected methods 
        // that getSolution depends on to achieve high coverage without setting up a full Simplex state.
        SimplexTableau tableau = spy(new SimplexTableau(data, true));

        // Mocking internal calls
        when(tableau.getOriginalNumDecisionVariables()).thenReturn(2);
        when(tableau.getNumObjectiveFunctions()).thenReturn(1);
        when(tableau.getNegativeDecisionVariableOffset()).thenReturn(3);
        when(tableau.getRhsOffset()).thenReturn(3);
        when(tableau.getBasicRow(0)).thenReturn(1); // Var 0 is basic in row 1
        when(tableau.getBasicRow(1)).thenReturn(2); // Var 1 is basic in row 2
        when(tableau.getBasicRow(3)).thenReturn(null); // Negative var row is null

        // Mocking data access
        when(tableau.getEntry(1, 3)).thenReturn(20.0);
        when(tableau.getEntry(2, 3)).thenReturn(8.0);

        // Mocking f.getValue (This requires f to be non-null in the real class)
