        when(tableau.getBasicRow(2)).thenReturn(1); // Var 1 (Duplicate)
        when(tableau.getEntry(1, 1)).thenReturn(10.0);

        // 4. Test Case: restrictToNonNegative = false (mostNegative is subtracted)
