    // Due to the complexity of SimplexTableau's constructor and private fields,
    // the following is the most robust way to test the specific logic of getSolution.

    @Test
    public void testGetSolution_CompleteLogic() throws Exception {
        // We create a subclass that overrides the protected methods to return controlled values
        SimplexTableau tableau = new SimplexTableau(new double[][]{{0}}, true) {
            private int varCount = 2;
            private int objCount = 1;
            private int rhsOffset = 2;
            private int negOffset = 3;
            private boolean restrict = false;

            @Override protected int getOriginalNumDecisionVariables() { return varCount; }
            @Override protected int getNumObjectiveFunctions() { return objCount; }
            @Override protected int getRhsOffset() { return rhsOffset; }
            @Override protected int getNegativeDecisionVariableOffset() { return negOffset; }
            @Override protected double getEntry(int r, int c) {
                if (r == 3 && c == 2) return -10.0; // mostNegative
                if (r == 1 && c == 2) return 50.0;  // Var 0 basic value
                if (r == 2 && c == 2) return 0.0;   // Var 1 basic value (null case)
                return 0.0;
            }
            @Override protected Integer getBasicRow(int row) {
                if (row == 3) return 0; // negative var row
                if (row == 1) return 1; // Var 0 basic row
                if (row == 2) return 2; // Var 1 basic row (but we will make it null for coverage)
